// === Tab: mySketch ===
let colors = []
let parameters = [] // [1.24, -1.25, -1.81, -1.91], [1.37, -1.85, -1.68, -1.38]
let canvasSize = 900
let loopCount = 0
let hits = Array(canvasSize).fill(0).map(x => Array(canvasSize).fill(0));

function setup() {
	createCanvas(canvasSize, canvasSize);
	background(255);

	// Add parameters
	if (parameters.length == 0) {
		for (let i = 0; i < 4; i++) {
			parameters.push(random(0, 1) + random([1, -2])) // random(-3, 3)
		}
	}

	// Add colors
	colorMode(HSB, 100);
	let mean = random(0, 100)
	for (let i = 0; i < 10; i++) {
		colors.push(abs(randomGaussian(mean, 10)) % 100)
	}
}

function draw() {

	// Plot
	if (loopCount >= 0) {
		image(getImage(), 0, 0);
	} else blend(getImage(), 0, 0, canvasSize, canvasSize, 0, 0, canvasSize, canvasSize, SOFT_LIGHT);
	loopCount++

	// Display parameters
	// fill(255)
	// noStroke()
	// rect(0, 0, canvasSize, 40)
	// fill(0)
	// textSize(30)
	// text(loopCount.toString(), 30, 30)
	// text(parameters.map(x => x.toFixed(2)).join(', '), 30, 30)
}

// Move particles
function next(x, y) {
	let nx = (sin(parameters[0]*y) + parameters[2] * cos(parameters[0]*x))
	let ny = (sin(parameters[1]*x) + parameters[3] * cos(parameters[1]*y))
	return [nx, ny]
}

function getImage() {
	// Calculate hits with blur
	let maxHits = 0;
	let x = 0;
	let y = 0;
	for (let round = 0; round < 5*10**4; round++) {
		[nx, ny] = next(x, y)

		// blur
		nx += random(-0.001, 0.001);
		ny += random(-0.001, 0.001);

		x = nx
		y = ny

		imgX = map(x, -3, 3, 0, canvasSize);
		imgY = map(y, -3, 3, 0, canvasSize);
		hits[int(imgX)][int(imgY)]++;
		maxHits = max(maxHits, hits[int(imgX)][int(imgY)])
	}

	// Create image by hits
	let newImage = createImage(canvasSize, canvasSize);
	newImage.loadPixels();
	for (let m = 0; m < canvasSize; m++) {
		for (let n = 0; n < canvasSize; n++) {
			if (hits[m][n] > 0) {
				num = map(hits[m][n], 0, maxHits, 0, 1);
				newImage.set(m, n, color(colors[0], 10+num*90, 100-num*80));
			}
		}
	}
	newImage.updatePixels();
	return newImage
}

